CREATE OR REPLACE VIEW public.crawl_font_share WITH (security_invoker=true) AS WITH base AS (SELECT s.*, sc.scope,count(*) OVER(PARTITION BY run_id,index_name,sc.scope) total FROM public.crawl_sites s JOIN public.crawl_runs r ON r.id=s.run_id CROSS JOIN (VALUES('all'::text),('en'::text)) sc(scope) WHERE s.ok AND r.status='finished' AND (sc.scope='all' OR s.lang ILIKE 'en%')), fonts AS (SELECT b.*,f.role,nullif(trim(f.family),'') family FROM base b CROSS JOIN LATERAL (VALUES('h1',b.type#>>'{rendered,h1,family}'),('body',b.type#>>'{rendered,body,family}')) f(role,family)) SELECT run_id,index_name,role,family,count(DISTINCT domain) sites,count(DISTINCT domain)::numeric/max(total) share,scope FROM fonts WHERE family IS NOT NULL GROUP BY run_id,index_name,role,family,scope;
CREATE OR REPLACE VIEW public.crawl_color_stats WITH (security_invoker=true) AS WITH base AS (SELECT s.*,sc.scope FROM public.crawl_sites s JOIN public.crawl_latest l ON s.run_id=l.id CROSS JOIN(VALUES('all'::text),('en'::text))sc(scope) WHERE s.ok AND(sc.scope='all' OR s.lang ILIKE 'en%')), channels AS(SELECT run_id,index_name,scope,CASE WHEN color->>'accent' ~ '^#[0-9a-fA-F]{6}$' THEN substring(color->>'accent' FROM 2) WHEN color->>'accent' ~ '^#[0-9a-fA-F]{3}$' THEN repeat(substring(color->>'accent' FROM 2 FOR 1),2)||repeat(substring(color->>'accent' FROM 3 FOR 1),2)||repeat(substring(color->>'accent' FROM 4 FOR 1),2) END hex FROM base), buckets AS(SELECT run_id,index_name,scope,'#'||lpad(to_hex(least(255,round(get_byte(decode(hex,'hex'),0)::numeric/16)::integer*16)),2,'0')||lpad(to_hex(least(255,round(get_byte(decode(hex,'hex'),1)::numeric/16)::integer*16)),2,'0')||lpad(to_hex(least(255,round(get_byte(decode(hex,'hex'),2)::numeric/16)::integer*16)),2,'0') hex FROM channels WHERE hex IS NOT NULL), counts AS(SELECT run_id,index_name,scope,hex,count(*) sites FROM buckets GROUP BY run_id,index_name,scope,hex), ranked AS(SELECT *,row_number() OVER(PARTITION BY run_id,index_name,scope ORDER BY sites DESC,hex) position FROM counts), accents AS(SELECT run_id,index_name,scope,jsonb_agg(jsonb_build_object('hex',hex,'count',sites) ORDER BY sites DESC,hex) accent_top FROM ranked WHERE position<=12 GROUP BY run_id,index_name,scope) SELECT b.run_id,b.index_name,count(*) FILTER(WHERE b.color->>'theme'='dark')::numeric/count(*) dark_share,avg((b.color->>'whitespace_ratio')::numeric) avg_whitespace,percentile_cont(0.5) WITHIN GROUP(ORDER BY (b.color->>'body_contrast')::double precision) median_body_contrast,coalesce(a.accent_top,'[]'::jsonb) accent_top,b.scope FROM base b LEFT JOIN accents a USING(run_id,index_name,scope) GROUP BY b.run_id,b.index_name,b.scope,a.accent_top;
CREATE OR REPLACE VIEW public.crawl_layout_share WITH(security_invoker=true) AS WITH base AS(SELECT s.*,sc.scope,count(*) OVER(PARTITION BY run_id,index_name,sc.scope) total,(layout->>'cta_radius_px')::numeric radius,(layout->>'grid_max_cols')::numeric cols,(type#>>'{declared,h1,size_px}')::numeric size,(type#>>'{declared,h1,letter_spacing_em}')::numeric tracking FROM public.crawl_sites s JOIN public.crawl_latest l ON s.run_id=l.id CROSS JOIN(VALUES('all'::text),('en'::text))sc(scope) WHERE s.ok AND(sc.scope='all' OR lang ILIKE 'en%')), dimensions AS(SELECT b.*,d.dimension,d.value FROM base b CROSS JOIN LATERAL(VALUES('h1_align',layout->>'h1_align'),('hero_media',layout->>'hero_media'),('cta_shape',CASE WHEN radius IS NULL THEN 'none' WHEN radius<=2 THEN 'sharp' WHEN radius<=12 THEN 'soft' WHEN radius<999 THEN 'round' ELSE 'pill' END),('grid_cols',CASE WHEN cols IS NULL THEN NULL WHEN cols>=5 THEN '5+' ELSE cols::integer::text END),('h1_size',CASE WHEN size IS NULL THEN NULL WHEN size<32 THEN '<32' WHEN size<48 THEN '32–47' WHEN size<64 THEN '48–63' WHEN size<96 THEN '64–95' ELSE '96+' END),('h1_tracking',CASE WHEN tracking IS NULL THEN NULL WHEN tracking< -0.02 THEN 'tight' WHEN tracking<=0.02 THEN 'normal' ELSE 'wide' END),('h1_case',CASE WHEN type#>>'{declared,h1,transform}'='uppercase' THEN 'uppercase' ELSE 'other' END))d(dimension,value)) SELECT run_id,index_name,dimension,value,count(DISTINCT domain) sites,count(DISTINCT domain)::numeric/max(total) share,scope FROM dimensions WHERE value IS NOT NULL GROUP BY run_id,index_name,dimension,value,scope;
CREATE OR REPLACE VIEW public.crawl_tech_share WITH(security_invoker=true) AS WITH base AS(SELECT s.*,sc.scope,count(*) OVER(PARTITION BY run_id,index_name,sc.scope) total FROM public.crawl_sites s JOIN public.crawl_latest l ON s.run_id=l.id CROSS JOIN(VALUES('all'::text),('en'::text))sc(scope) WHERE s.ok AND(sc.scope='all' OR lang ILIKE 'en%')) SELECT b.run_id,b.index_name,t.key tech,count(DISTINCT domain) sites,count(DISTINCT domain)::numeric/max(total) share,scope FROM base b CROSS JOIN LATERAL jsonb_each(coalesce(b.tech,'{}'::jsonb))t WHERE t.value='true'::jsonb AND t.key IN('next','nuxt','framer','webflow','wordpress','shopify','squarespace','wix','astro','gatsby','sveltekit','tailwind','gsap','lenis','three','lottie','webgl_canvas') GROUP BY run_id,index_name,t.key,scope;
CREATE OR REPLACE VIEW public.crawl_cta_phrases WITH(security_invoker=true) AS WITH base AS(SELECT s.*,sc.scope,count(*) OVER(PARTITION BY run_id,index_name,sc.scope) total FROM public.crawl_sites s JOIN public.crawl_latest l ON s.run_id=l.id CROSS JOIN(VALUES('all'::text),('en'::text))sc(scope) WHERE s.ok AND(sc.scope='all' OR lang ILIKE 'en%')), counts AS(SELECT run_id,index_name,lower(trim(p.value#>>'{}')) phrase,count(DISTINCT domain) sites,count(DISTINCT domain)::numeric/max(total) share,scope FROM base CROSS JOIN LATERAL jsonb_array_elements(coalesce(lexicon->'ctas','[]'::jsonb))p(value) WHERE jsonb_typeof(p.value)='string' AND trim(p.value#>>'{}')<>'' GROUP BY run_id,index_name,scope,lower(trim(p.value#>>'{}'))), ranked AS(SELECT *,row_number() OVER(PARTITION BY run_id,index_name,scope ORDER BY sites DESC,phrase) position FROM counts) SELECT run_id,index_name,phrase,sites,share,scope FROM ranked WHERE position<=50;
CREATE OR REPLACE VIEW public.crawl_h1_words WITH(security_invoker=true) AS WITH words AS(SELECT s.run_id,s.index_name,s.domain,sc.scope,w.word FROM public.crawl_sites s JOIN public.crawl_latest l ON s.run_id=l.id CROSS JOIN(VALUES('all'::text),('en'::text))sc(scope) CROSS JOIN LATERAL regexp_split_to_table(lower(coalesce(lexicon->>'h1','')),'[^a-z]+')w(word) WHERE s.ok AND(sc.scope='all' OR lang ILIKE 'en%')), counts AS(SELECT run_id,index_name,word,count(DISTINCT domain) sites,scope FROM words WHERE length(word)>=3 AND word<>ALL(ARRAY['the','and','for','are','but','not','you','your','yours','our','ours','their','they','them','this','that','these','those','with','from','into','onto','about','above','below','over','under','out','off','all','any','each','few','more','most','other','some','such','only','own','same','than','too','very','can','will','just','should','now','was','were','been','being','have','has','had','does','did','doing','its','his','her','hers','she','him','who','what','when','where','why','how','which','while','also','here','there','then','once','again','because','through','between','before','after']) GROUP BY run_id,index_name,word,scope), ranked AS(SELECT *,row_number() OVER(PARTITION BY run_id,index_name,scope ORDER BY sites DESC,word) position FROM counts) SELECT run_id,index_name,word,sites,scope FROM ranked WHERE position<=100;
CREATE VIEW public.crawl_spread WITH(security_invoker=true) AS WITH gf AS(SELECT lower(family) family,category FROM public.gfont_snapshots WHERE captured_on=(SELECT max(captured_on) FROM public.gfont_snapshots)), base AS(SELECT s.*,sc.scope FROM public.crawl_sites s JOIN public.crawl_latest l ON s.run_id=l.id OR s.run_id=l.prev_id CROSS JOIN(VALUES('all'::text),('en'::text))sc(scope) WHERE s.ok AND(sc.scope='all' OR lang ILIKE 'en%')), signals AS(SELECT b.run_id,b.index_name,b.scope,d.signal,d.label,coalesce(d.hit,false) hit FROM base b CROSS JOIN LATERAL(VALUES('dark_theme','Dark theme',color->>'theme'='dark'),('high_whitespace','Whitespace ≥ 60%',(composition->>'whitespace_ratio')::numeric>=0.6),('tight_tracking','Tight headline tracking',(type#>>'{declared,h1,letter_spacing_em}')::numeric< -0.02),('big_headline','Headline ≥ 48px',(type#>>'{declared,h1,size_px}')::numeric>=48),('pill_cta','Pill buttons',(layout->>'cta_radius_px')::numeric=999),('webgl_hero','WebGL / 3D hero',layout->>'hero_media'='webgl'),('video_hero','Video hero',layout->>'hero_media'='video'),('centered_headline','Centered headline',layout->>'h1_align'='center'),('serif_headline','Serif headline',coalesce(type#>>'{rendered,h1,family}','') !~* 'sans' AND (EXISTS(SELECT 1 FROM gf WHERE gf.family=lower(type#>>'{rendered,h1,family}') AND category='serif') OR type#>>'{rendered,h1,family}' ~* 'serif|times|georgia|garamond|caslon|tiempos|fraunces|newsreader|playfair|editorial')),('mono_anywhere','Monospace in use',EXISTS(SELECT 1 FROM gf WHERE gf.family IN(lower(type#>>'{rendered,h1,family}'),lower(type#>>'{rendered,body,family}')) AND category='monospace') OR concat(type#>>'{rendered,h1,family}',' ',type#>>'{rendered,body,family}') ~* 'mono|code|courier'),('system_font','System UI body text',type#>>'{rendered,body,family}'='System UI'),('tailwind','Tailwind',tech->'tailwind'='true'::jsonb))d(signal,label,hit)), shares AS(SELECT run_id,scope,signal,label,avg(hit::integer::numeric) FILTER(WHERE index_name='vanguard') v,avg(hit::integer::numeric) FILTER(WHERE index_name='mainstream') m FROM signals GROUP BY run_id,scope,signal,label) SELECT n.scope,n.signal,n.label,n.v vanguard_share,n.m mainstream_share,round((n.v-n.m)*100,1) spread_pts,round((p.v-p.m)*100,1) prev_spread_pts FROM shares n JOIN public.crawl_latest l ON n.run_id=l.id LEFT JOIN shares p ON p.run_id=l.prev_id AND p.scope=n.scope AND p.signal=n.signal;
GRANT SELECT ON public.crawl_font_share,public.crawl_color_stats,public.crawl_layout_share,public.crawl_tech_share,public.crawl_cta_phrases,public.crawl_h1_words,public.crawl_spread TO anon,authenticated,service_role;